    mark_color = Counter(v for _, _, v in marks).most_common(1)[0][0] if marks else bar_color

    # Extend horizontal-edge bars vertically and vertical-edge bars
    # horizontally, using the isolated-object color.
    for r, c in edge:
        if r == 0:
            dr, dc = 1, 0
        elif r == h - 1:
            dr, dc = -1, 0
        elif c == 0:
